import { githubNumber, readPullPages, toGitHubRows, type GitHubClientDeps } from '../client.js'
import type { GitHubConfig } from '../config.js'

export const github_pullRequestsRaw = rawTable({ database: 'default', name: 'github_pull_requests_raw' })

export async function* readPullRequests(context: FetchContext, repo: string, config: GitHubConfig, deps: GitHubClientDeps) {
  for await (const page of readPullPages(context, repo, config, deps)) {
    yield { rows: toGitHubRows(page, repo, (pull) => githubNumber(pull, 'number')) }
  }
}

import { rawTable, type ReadContext, type TimestampRange, type TimestampWindowState } from '@chkit/plugin-ingest'

import { githubNumber, readGitHubPages, readPullPages, toGitHubRows, updatedItems, type GitHubClientDeps } from '../client.js'
import type { GitHubConfig } from '../config.js'

export const github_pullRequestCommentsRaw = rawTable({ database: 'default', name: 'github_pull_request_comments_raw' })

export async function* readPullRequestComments(context: ReadContext<TimestampRange, TimestampWindowState>, repo: string, config: GitHubConfig, deps: GitHubClientDeps) {
  // This reader owns its discovery and window; the PR metadata stream need not have run.
  for await (const pulls of readPullPages(context, repo, config, deps)) {
    for (const pull of pulls) {
      const number = githubNumber(pull, 'number')
      for await (const page of readGitHubPages(context, { path: `/repos/${repo}/issues/${number}/comments`, params: { since: context.selection.from.toISOString() } }, config, deps)) {
        yield { rows: toGitHubRows(updatedItems(page, context.selection), repo, (comment) => githubNumber(comment, 'id'), { pull_number: number }) }
      }
    }
  }
}

import { rawTable, type ReadContext, type TimestampRange, type TimestampWindowState } from '@chkit/plugin-ingest'

import { githubNumber, pullNumber, readGitHubPages, toGitHubRows, updatedItems, type GitHubClientDeps } from '../client.js'
import type { GitHubConfig } from '../config.js'

export const github_pullRequestReviewCommentsRaw = rawTable({ database: 'default', name: 'github_pull_request_review_comments_raw' })

export async function* readPullRequestReviewComments(context: ReadContext<TimestampRange, TimestampWindowState>, repo: string, config: GitHubConfig, deps: GitHubClientDeps) {
  for await (const page of readGitHubPages(context, { path: `/repos/${repo}/pulls/comments`, params: {
    since: context.selection.from.toISOString(), sort: 'updated', direction: 'asc',
  } }, config, deps)) {
    for (const comment of updatedItems(page, context.selection)) {
      yield { rows: toGitHubRows([comment], repo, (item) => githubNumber(item, 'id'), { pull_number: pullNumber(comment, repo) }) }
    }
  }
}

